"""Writes dist/info-escenes.js: for the activities with an «Informació» panel (the four dives since 0.32; the cassola, the castells,
the orchestra, the bandstand and the sound places since 0.33), each scene or item's picture (a small JPEG, inside the file) and up to three plain lines
about what it shows, from production/info/escenes.json and production/info/img/. Run after changing either."""
import base64,json,struct
from pathlib import Path
def jpeg_bytes(path):
    """The JPEG as it is, without the content-credentials box (APP11 «JP», 5.7 KB) that a copy of the file can carry and the panel does not need."""
    b=path.read_bytes();assert b[:2]==b'\xff\xd8',path;out=bytearray(b[:2]);i=2
    while i<len(b) and b[i]==0xFF:
        m=b[i+1]
        if m==0xDA:out+=b[i:];return bytes(out)
        L=struct.unpack('>H',b[i+2:i+4])[0]
        if not(m==0xEB and b[i+4:i+6]==b'JP'):out+=b[i:i+2+L]
        i+=2+L
    return b
here=Path(__file__).resolve().parent;root=here.parent.parent
data=json.loads((here/'escenes.json').read_text())
out={}
for key,items in data.items():
    rows=[]
    for i,it in enumerate(items):
        img=here/'img'/f'{key}_{i+1:02d}.jpg'
        assert img.exists(),img;assert 1<=len(it['l'])<=3,(key,i)
        rows.append({'t':it['t'],'l':it['l'],'img':'data:image/jpeg;base64,'+base64.b64encode(jpeg_bytes(img)).decode()})
    out[key]=rows
HEAD={'vehicles':'Les peces del taller a cada racó de la casa (sis carrosseries, sis menes de rodes i sis accessoris per racó: l’habitació; des de la 0.56, la sala, amb els vehicles d’emergències, des de la 0.57, el pati, amb els vehicles d’obres, des de la 0.58, el passadís, amb el tren, i des de la 0.59, el bany, amb els vehicles de l’aigua i de l’aire; des de la 0.60, quan el quart vehicle d’un racó arriba al garatge, els vehicles fets al racó desfilen junts per davant de l’habitació) i cada racó a les quatre hores del dia: què fa cada peça quan el vehicle es posa en marxa.','color-rain':'Els vint fulls marbrejats dels cinc tallers: com es fa cada patró i quina música l’acompanya.','flower':'Les vint flors reals dels cinc jardins: com són, com s’obren i qui les visita.','fira':'Les cinc atraccions, les seves sorpreses, el final de cadascuna i la seva música. Cada atracció es veu amb quatre llums: matí, tarda, posta i nit.','encaix':'Els cinc mons, les quatre llums de cadascun, les figures que hi encaixen i la música de cada món.','masia':'Els cinc personatges, les seves històries i el sopar.','viatge':'El globus d’aire calent, les cinc rutes i el dia sencer amb les estacions.','pot':'Les {n} criatures: d’on ve el seu mite i què passa a l’escena.','castells':'Les parts del castell, els tipus de castell i la festa.','orchestra':'Les {n} seccions de l’orquestra que es desperten.','pinta':'Els {n} paisatges que es pinten, cadascun a les quatre estacions.','sounds':'Els {n} instruments del templet i com sonen.','sources':'Els {n} llocs i d’on ve el seu so.'}
head={k:HEAD.get(k,'Les {n} escenes i què s’hi representa.').format(n=len(v)) for k,v in out.items()}
js=('// Generated by production/info/make_info.py: the «Informació» panels (a picture and up to three plain lines per scene or item, and a heading per activity).\n'
    'export const SCENE_INFO=Object.freeze('+json.dumps(out,ensure_ascii=False,separators=(',',':'))+');\n'
    'export const SCENE_INFO_HEAD=Object.freeze('+json.dumps(head,ensure_ascii=False)+');\n')
# The pictures of the home cards of the four dives (0.35): drawing them live compiled their big WebGL shaders while the menu opened,
# and the menu hung for many seconds. Captured from the live preview of 0.34 (488 × 273, the preview's own size at most); the giants (0.36)
# from tools/gegants-frames.mjs (El viatge en globus, 0.43, from tools/viatge-frames.mjs: the valley in spring, morning), the preview's moment (the humpback breach); Pinta el món (0.38) from tools/pinta-frames.mjs (the spring rainbow of the valley); La nova Flor de paper (0.51) from tools/flor-info.mjs (the meadow, three flowers open); Gotes de pintura (0.52) from tools/marbre-info.mjs (Istanbul's «Cadena de cors» since 0.52.1); La nova Pluja de colors (0.53) from tools/pluja-info.mjs (Primera llum, full); El taller de vehicles (0.53) from tools/vehicles-info.mjs (the finished family car on the bench; three.js cannot build its scene while the menu opens).
cards={k:'data:image/jpeg;base64,'+base64.b64encode(jpeg_bytes(here/'cards'/f'{k}.jpg')).decode() for k in ['jelly','jungle','savanna','well','giants','pinta','masia','viatge','flower','color-rain','vehicles','pluja-colors']}
js+='export const CARD_IMG=Object.freeze('+json.dumps(cards,separators=(',',':'))+');\n'
(root/'dist'/'info-escenes.js').write_text(js);print('scenes',{k:len(v) for k,v in out.items()},len(js),'bytes')
